<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_avatar( $user_id = 0, $size = 64 ) { if ( function_exists( 'bp_core_fetch_avatar' ) ) { return bp_core_fetch_avatar( array( 'item_id' => $user_id, 'type' => 'thumb', 'width' => $size, 'height' => $size, 'html' => false ) ); } return get_avatar_url( $user_id ?: get_current_user_id(), array( 'size' => $size ) ); }
function sd_get_member_url( $user_id ) { return function_exists( 'bp_core_get_user_domain' ) ? bp_core_get_user_domain( $user_id ) : get_author_posts_url( $user_id ); }
function sd_render_empty( $title, $message ) { echo '<div class="sd-card sd-empty"><h3>' . esc_html( $title ) . '</h3><p>' . esc_html( $message ) . '</p></div>'; }
function sd_get_page_url( $slug, $fallback = '/' ) { $page = get_page_by_path( $slug ); return $page ? get_permalink( $page ) : home_url( $fallback ); }
function sd_render_site_branding( $footer = false ) { ?><a class="sd-site-brand" href="<?php echo esc_url( home_url( '/' ) ); ?>" rel="home"><?php if ( has_custom_logo() && ( ! $footer || sd_get_option( 'sd_footer_logo' ) ) ) { the_custom_logo(); } else { ?><span class="sd-brand-mark">S</span><span><?php bloginfo( 'name' ); ?></span><?php } ?></a><?php }
function sd_social_links() { $links = array( 'facebook' => 'Facebook', 'instagram' => 'Instagram', 'youtube' => 'YouTube', 'tiktok' => 'TikTok', 'linkedin' => 'LinkedIn', 'x' => 'X', 'github' => 'GitHub', 'whatsapp' => 'WhatsApp' ); $out = ''; foreach ( $links as $key => $label ) { $url = get_theme_mod( 'sd_social_' . $key, '' ); if ( $url ) { $out .= '<a class="sd-social-link" href="' . esc_url( $url ) . '" target="_blank" rel="noopener noreferrer" aria-label="' . esc_attr( $label ) . '">' . esc_html( strtoupper( substr( $label, 0, 1 ) ) ) . '</a>'; } } return $out; }
